INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100019, now(), now(), 'seed', '<h2>Politique de confidentialité</h2><p>Beauté Élégante Paris, 15 rue de la Paix, 75002 Paris, est responsable du traitement de vos données au sens du RGPD.</p><h3>Données collectées</h3><ul><li>Identité et coordonnées de livraison</li><li>Historique de commandes et de retours</li><li>Données de navigation, si vous acceptez les cookies de mesure</li></ul><h3>Durées de conservation</h3><p>Les données de commande sont conservées dix ans au titre des obligations comptables ; les données de compte, trois ans après votre dernière activité.</p><h3>Vos droits</h3><p>Accès, rectification, effacement, portabilité et opposition s''exercent auprès de <a href="mailto:dpo@beaute-elegante.fr">dpo@beaute-elegante.fr</a>. Vous pouvez saisir la CNIL à tout moment.</p>', 'Politique de confidentialité', 'Politique de confidentialité', null, null, null, null, 'fr', -10010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100020, now(), now(), 'seed', '<h2>Privacy policy</h2><p>Beauté Élégante Paris, 15 rue de la Paix, 75002 Paris, is the controller of your data under the GDPR.</p><h3>What we collect</h3><ul><li>Identity and delivery details</li><li>Order and return history</li><li>Browsing data, if you accept measurement cookies</li></ul><h3>How long we keep it</h3><p>Order data is kept for ten years under accounting obligations; account data for three years after your last activity.</p><h3>Your rights</h3><p>Access, rectification, erasure, portability and objection can be exercised at <a href="mailto:dpo@beaute-elegante.fr">dpo@beaute-elegante.fr</a>. You may lodge a complaint with the CNIL at any time.</p>', 'Privacy policy', 'Privacy policy', null, null, null, null, 'en', -10010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-1001, '65f020632bc46470c104b76f', -10010, 1, 'LIVE', now() - interval '30 days', null, '[{"language": "fr", "title": "Politique de confidentialité", "body": "<h2>Politique de confidentialité</h2><p>Beauté Élégante Paris, 15 rue de la Paix, 75002 Paris, est responsable du traitement de vos données au sens du RGPD.</p><h3>Données collectées</h3><ul><li>Identité et coordonnées de livraison</li><li>Historique de commandes et de retours</li><li>Données de navigation, si vous acceptez les cookies de mesure</li></ul><h3>Durées de conservation</h3><p>Les données de commande sont conservées dix ans au titre des obligations comptables ; les données de compte, trois ans après votre dernière activité.</p><h3>Vos droits</h3><p>Accès, rectification, effacement, portabilité et opposition s''exercent auprès de <a href=\"mailto:dpo@beaute-elegante.fr\">dpo@beaute-elegante.fr</a>. Vous pouvez saisir la CNIL à tout moment.</p>", "state": "TRANSLATED"}, {"language": "en", "title": "Privacy policy", "body": "<h2>Privacy policy</h2><p>Beauté Élégante Paris, 15 rue de la Paix, 75002 Paris, is the controller of your data under the GDPR.</p><h3>What we collect</h3><ul><li>Identity and delivery details</li><li>Order and return history</li><li>Browsing data, if you accept measurement cookies</li></ul><h3>How long we keep it</h3><p>Order data is kept for ten years under accounting obligations; account data for three years after your last activity.</p><h3>Your rights</h3><p>Access, rectification, erasure, portability and objection can be exercised at <a href=\"mailto:dpo@beaute-elegante.fr\">dpo@beaute-elegante.fr</a>. You may lodge a complaint with the CNIL at any time.</p>", "state": "TRANSLATED"}]', now(), 'seed')
