INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100021, now(), now(), 'seed', '<h2>Politique de retour</h2><p>Trente jours pour changer d''avis, à compter de la réception du colis.</p><h3>Conditions</h3><ul><li>Produit non ouvert, scellé d''hygiène intact</li><li>Emballage d''origine et preuve d''achat</li><li>Étiquette de retour prépayée fournie dans votre espace client</li></ul><h3>Remboursement</h3><p>Sous cinq jours ouvrés après réception, sur le moyen de paiement d''origine. Les frais de livraison initiaux sont remboursés en cas de produit défectueux.</p><p><em>Version 2 — les retours en boutique sont désormais acceptés sans rendez-vous.</em></p>', 'Politique de retour', 'Politique de retour', null, null, null, null, 'fr', -10011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100022, now(), now(), 'seed', '<h2>Returns policy</h2><p>Thirty days to change your mind, counted from the day the parcel arrives.</p><h3>Conditions</h3><ul><li>Unopened item with the hygiene seal intact</li><li>Original packaging and proof of purchase</li><li>A prepaid return label, available in your account</li></ul><h3>Refunds</h3><p>Within five working days of receipt, to the original payment method. Original delivery charges are refunded when the item is faulty.</p><p><em>Version 2 — boutique returns are now accepted without an appointment.</em></p>', 'Returns policy', 'Returns policy', null, null, null, null, 'en', -10011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
