VALUES (-100023, now(), now(), 'seed', '<h2>Conditions de livraison</h2><p>Préparation le jour même pour toute commande validée avant 14h, du lundi au vendredi.</p><table><tr><th>Destination</th><th>Délai</th><th>Tarif</th></tr><tr><td>France métropolitaine</td><td>2–3 jours</td><td>4,90 €</td></tr><tr><td>Union européenne</td><td>3–6 jours</td><td>9,90 €</td></tr><tr><td>Suisse et Royaume-Uni</td><td>4–8 jours</td><td>14,90 €</td></tr></table><p>Les droits de douane éventuels hors UE restent à la charge du destinataire.</p>', 'Conditions de livraison', 'Conditions de livraison', null, null, null, null, 'fr', -10012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100024, now(), now(), 'seed', '<h2>Shipping policy</h2><p>Same-day packing for every order confirmed before 2pm, Monday to Friday.</p><table><tr><th>Destination</th><th>Time</th><th>Rate</th></tr><tr><td>Mainland France</td><td>2–3 days</td><td>€4.90</td></tr><tr><td>European Union</td><td>3–6 days</td><td>€9.90</td></tr><tr><td>Switzerland and the UK</td><td>4–8 days</td><td>€14.90</td></tr></table><p>Any customs duties outside the EU are payable by the recipient.</p>', 'Shipping policy', 'Shipping policy', null, null, null, null, 'en', -10012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
