INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100025, now(), now(), 'seed', '<h2>Cookies</h2><p>Nous déposons trois familles de cookies, dont une seule est exemptée de consentement.</p><ul><li><strong>Essentiels</strong> — panier, session, sécurité. Toujours actifs.</li><li><strong>Mesure d''audience</strong> — statistiques agrégées, 13 mois.</li><li><strong>Personnalisation</strong> — recommandations produits, 6 mois.</li></ul><p>Votre choix est enregistré pour six mois et modifiable à tout moment depuis le lien « Préférences cookies » en pied de page.</p>', 'Politique relative aux cookies', 'Politique relative aux cookies', null, null, null, null, 'fr', -10013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100026, now(), now(), 'seed', '<h2>Cookies</h2><p>We set three families of cookies, only one of which is exempt from consent.</p><ul><li><strong>Essential</strong> — cart, session, security. Always on.</li><li><strong>Measurement</strong> — aggregate statistics, 13 months.</li><li><strong>Personalisation</strong> — product recommendations, 6 months.</li></ul><p>Your choice is stored for six months and can be changed at any time from the “Cookie preferences” link in the footer.</p>', 'Cookie policy', 'Cookie policy', null, null, null, null, 'en', -10013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
